-- Load official college facts (rounds 1+2). Re-runnable: replaces colleges.facts for the four applying colleges.
update public.colleges set facts = '{"as_of": "Oct 27, 2026 (Scorecard Jun 2026; NCES 2024-25 costs; college Common Data Sets 2025-26)", "stats": {"undergrad_enrollment": 34454, "admit_rate": 0.1564, "grad_rate_6yr": 0.9319, "retention_rate": 0.9747, "student_faculty_ratio": "11:1", "in_state_tuition_fees": 17736, "in_state_cost_of_attendance": 36932, "avg_net_price_all": 14362, "median_earnings_10yr": 92832, "drive_miles": 366, "drive_hours": 6.5}, "net_price_by_income": {"0-30000": 3155, "30001-48000": 3372, "48001-75000": 5768, "75001-110000": 13888, "110001-plus": 28625}, "business": {"school": "Stephen M. Ross School of Business (BBA)", "admission_model": "Direct first-year admission since Fall 2024: choose Ross on the Common App and submit the Ross BBA Admissions Portfolio (SlideRoom). EA Nov 1; RD and portfolio Feb 1.", "class_size": "534 first-years entered Fall 2025 — 924 admitted from 13,019 applicants (about 7%); 51% from Michigan", "academic_feel": "Core classes in cohort sections of about 80. Ross’s official core grading guideline caps A-range grades at 40% of a class. Junior-year Integrative Semester.", "recruiting_and_outcomes": "Class of 2025: over 98% had offers by Sept 30; median salary over $100K. Financial services 46%, consulting 19%, tech 9%. 279 hiring firms.", "signature_programs": ["Ross Integrative Semester (junior-year integrated core + business challenge)", "Signature Learning Experience every year, starting with BA 100", "MAP capstone team projects for sponsor organizations"], "aacsb": true, "business_clubs": ["BBA Marketing Club", "BBA Finance Club", "MECC Consulting Group (pro bono)", "Michigan Business Women", "Michigan Interactive Investments"], "how_it_fits_campus": "A school within a school: its own building, cohorts, council and clubs. First-years still take calculus, writing and economics across U-M.", "school_within_school_note": "Selective finance and consulting clubs recruit at Festifall, before classes start, and are interview-heavy (student reporting)."}, "sources": [{"label": "College Scorecard", "url": "https://collegescorecard.ed.gov/school/?170976-University-of-Michigan-Ann-Arbor", "year": "2026 release"}, {"label": "NCES College Navigator", "url": "https://nces.ed.gov/collegenavigator/?id=170976", "year": "2024-25"}, {"label": "Ross first-year applicants", "url": "https://michiganross.umich.edu/undergraduate/bba/admissions/first-year-applicants", "year": "2026"}, {"label": "Ross BBA core", "url": "https://rossweb.bus.umich.edu/academics/curriculum/core-curriculum/bba/", "year": "current"}, {"label": "U-M Common Data Set 2025-26", "url": "https://obp.umich.edu/wp-content/uploads/pubdata/cds/cds_2025-26_umaa.pdf", "year": "2025-26"}, {"label": "Ross BBA Class of 2029", "url": "https://michiganross.umich.edu/news/class-changemakers-meet-michigan-ross-bba-class-2029", "year": "2025"}, {"label": "Ross 2025 BBA employment", "url": "https://michiganross.umich.edu/news/michigan-ross-undergraduates-remain-high-demand-secure-top-salaries-according-2025-employment", "year": "2025"}, {"label": "Ross BBA grading guideline", "url": "https://rossweb.bus.umich.edu/academics/bba-grading-scales-distribution", "year": "current"}, {"label": "U-M first-year housing", "url": "https://housing.umich.edu/first-year-application-instructions/", "year": "2026"}], "housing": {"first_year_requirement": "Not required, but 96% of first-years live on campus", "room_and_board": "$17,220 (double room, largest meal plan, 2026-27)", "residence_options": ["Traditional halls on Central, North and Hill", "Theme communities", "Michigan Learning Communities (apply with an essay in the housing application)"], "business_living_community": null, "application_opens": "Opens after the enrollment deposit; in 2026 it ran Apr 2–May 11. Applying earlier within the window gives no priority.", "notes": "No guarantee of a specific hall; Early Decision admits get no housing priority."}, "campus": {"setting": "Ann Arbor, a small-city college town about 40 miles west of Detroit", "pct_in_state": "About 57% of undergrads", "student_orgs": "1,600+ registered organizations", "greek_life": "11% of men, 16% of women", "athletics": "NCAA Division I, Big Ten", "traditions": ["Big Ten football at Michigan Stadium", "Festifall organization fair to start the year", "Large research university with 19 schools and colleges"], "climate_note": "Southern Michigan winters, far less snow than the U.P."}}'::jsonb where id = '00000000-0000-4000-a000-000000000001';
update public.colleges set facts = '{"as_of": "Oct 27, 2026 (Scorecard Jun 2026; NCES 2024-25 costs; college Common Data Sets 2025-26)", "stats": {"undergrad_enrollment": 41234, "admit_rate": 0.848, "grad_rate_6yr": 0.803, "retention_rate": 0.9005, "student_faculty_ratio": "17:1", "in_state_tuition_fees": 16458, "in_state_cost_of_attendance": 34240, "avg_net_price_all": 21322, "median_earnings_10yr": 74168, "drive_miles": 322, "drive_hours": 5.5}, "net_price_by_income": {"0-30000": 11741, "30001-48000": 11883, "48001-75000": 14300, "75001-110000": 22082, "110001-plus": 30356}, "business": {"school": "Eli Broad College of Business", "admission_model": "No separate application. MSU fall admits listing an eligible major are considered for direct admission to Broad (limited space). Others start as Business Preference and apply after 28+ credits; direct admits keep their spot with a 3.0 GPA.", "class_size": "About 1,170 business graduates in the Class of 2025", "academic_feel": "Large, Michigan-rooted business school. First-years do Wisdom Project interviews with alumni; majors are declared after core courses.", "recruiting_and_outcomes": "Class of 2025: 99% placement; median salary $70,000; 63% start their careers in Michigan. Employers include Deloitte, EY, KPMG, PwC, Ford, GM and Amazon.", "signature_programs": ["Supply chain management, ranked #1–#2 nationally (U.S. News)", "Residential Business Community", "Student Investment Fund", "The Wisdom Project (first-year alumni interviews)"], "aacsb": true, "business_clubs": ["Accounting Student Association", "MSU Marketing Association", "Supply Chain Management Association", "National Association of Black Accountants", "Phi Chi Theta"], "how_it_fits_campus": "Many students start as Business Preference in the wider university and join Broad after the secondary review."}, "sources": [{"label": "College Scorecard", "url": "https://collegescorecard.ed.gov/school/?171100-Michigan-State-University", "year": "2026 release"}, {"label": "NCES College Navigator", "url": "https://nces.ed.gov/collegenavigator/?id=171100", "year": "2024-25"}, {"label": "Broad direct admission", "url": "https://broad.msu.edu/undergraduate/admissions/direct", "year": "2026"}, {"label": "Broad rankings", "url": "https://broad.msu.edu/rankings/", "year": "2027 ed."}, {"label": "MSU Common Data Set 2025-26", "url": "https://ir.msu.edu/-/media/assets/ir/docs/cds/cds-2025-2026.pdf", "year": "2025-26"}, {"label": "MSU incoming student housing", "url": "https://liveon.msu.edu/incoming-student-housing", "year": "2027-28"}, {"label": "Broad Residential Business Community", "url": "https://broad.msu.edu/undergraduate/opportunities/rbc/", "year": "current"}, {"label": "Broad employment report", "url": "https://broad.msu.edu/app/uploads/2026/01/Palmer-Undergrad-Employment-Report-25.pdf", "year": "Class of 2025"}], "housing": {"first_year_requirement": "Required: first four semesters on campus (limited exceptions)", "room_and_board": "$12,928 ($5,338 housing + $7,590 food, 2026-27)", "residence_options": ["27 halls in five neighborhoods (Brody, East, North, River Trail, South)", "Living-Learning Communities and Residential Colleges", "Honors housing"], "business_living_community": "Residential Business Community — first-year business students in East McDonel Hall with reserved class seats and a 1-credit seminar (separate from Broad direct admission)", "application_opens": "Posted for 2027-28: $50 fee, $175 advance payment (refundable before July 15, 2027) and contract due in early May; preferences due in June.", "notes": "Students rank preferences; the office assigns rooms. Fees can be waived if the Student Aid Index is below 0."}, "campus": {"setting": "East Lansing, a suburban college town next to the state capital", "pct_in_state": "About 83% of undergrads", "student_orgs": "1,000+ registered organizations", "greek_life": "12% of men, 13% of women", "athletics": "NCAA Division I, Big Ten", "traditions": ["Spartans and Sparty", "Land-grant university with residential colleges", "Five residential neighborhoods with their own dining"], "climate_note": "Southern Michigan winters, far less snow than the U.P."}}'::jsonb where id = '00000000-0000-4000-a000-000000000002';
update public.colleges set facts = '{"as_of": "Oct 27, 2026 (Scorecard Jun 2026; NCES 2024-25 costs; college Common Data Sets 2025-26)", "stats": {"undergrad_enrollment": 6013, "admit_rate": 0.9243, "grad_rate_6yr": 0.6995, "retention_rate": 0.8882, "student_faculty_ratio": "13:1", "in_state_tuition_fees": 19123, "in_state_cost_of_attendance": 36158, "avg_net_price_all": 13446, "median_earnings_10yr": 84681, "drive_miles": 182, "drive_hours": 4}, "net_price_by_income": {"0-30000": null, "30001-48000": 1188, "48001-75000": 5282, "75001-110000": 12038, "110001-plus": 23346}, "business": {"school": "College of Business", "admission_model": "No separate business application: admitted through Michigan Tech’s general admission into a business major, or General Business with up to three semesters to choose.", "class_size": "Small: business is about 8% of bachelor’s degrees; college enrollment up 38% in five years", "academic_feel": "STEM-focused business at a tech university: business analytics, engineering management, and easy dual majors.", "recruiting_and_outcomes": "College cites 96% job placement (year not stated); university-wide 94.6% (2025).", "signature_programs": ["Applied Portfolio Management Program: about $3M real investment fund", "Enterprise Business Initiative / Enterprise teams", "Bob Mark Business Model Competition and New Venture Competition", "Spring-break industry visits"], "aacsb": true, "business_clubs": ["Applied Portfolio Management Program", "American Marketing Association", "Beta Gamma Sigma", "Omicron Delta Epsilon", "Husky Innovate"], "how_it_fits_campus": "A small business college inside a STEM university; many students pair business with engineering or computing."}, "sources": [{"label": "College Scorecard", "url": "https://collegescorecard.ed.gov/school/?171128-Michigan-Technological-University", "year": "2026 release"}, {"label": "NCES College Navigator", "url": "https://nces.ed.gov/collegenavigator/?id=171128", "year": "2024-25"}, {"label": "MTU College of Business", "url": "https://www.mtu.edu/business/college/profile/", "year": "current"}, {"label": "MTU cost of attendance", "url": "https://www.mtu.edu/finaid/tuition/cost/", "year": "2026-27"}, {"label": "MTU Common Data Set 2025-26", "url": "https://www.mtu.edu/institutional-research/cds/files/cds-2025-2026.xlsx", "year": "2025-26"}, {"label": "MTU housing & dining", "url": "https://www.mtu.edu/admissions/life/housing-dining/", "year": "current"}, {"label": "MTU business organizations", "url": "https://www.mtu.edu/business/undergraduate/organizations/", "year": "current"}, {"label": "MTU Winter Carnival", "url": "https://www.mtu.edu/winter-carnival/about/history/", "year": "current"}], "housing": {"first_year_requirement": "Required in the first year. Presidential Scholars (Lily’s likely merit tier) must live on campus two years.", "room_and_board": "$14,321 (2026-27)", "residence_options": ["Traditional halls: Douglass Houghton, McNair, Wadsworth", "First-Year Experience community in Wadsworth", "East Hall suites and Hillside Place apartments (second year on)"], "business_living_community": null, "application_opens": "Housing contract opens in January after the enrollment deposit; roommate matching early March; roommate choices due June 1.", "notes": "95.6% of first-years live on campus."}, "campus": {"setting": "Houghton, a small town on the Keweenaw Waterway near Lake Superior", "pct_in_state": "About 77% of undergrads", "student_orgs": "Many; business college alone lists about a dozen groups", "greek_life": "About 11–12% of undergrads", "athletics": "NCAA Division II (GLIAC); men’s hockey Division I (CCHA)", "traditions": ["Winter Carnival with giant snow statues since the 1920s", "STEM-focused Huskies (black and gold)", "Enterprise teams doing real client projects"], "climate_note": "Heavy lake-effect snow — over 130 inches in some seasons."}}'::jsonb where id = '00000000-0000-4000-a000-000000000003';
update public.colleges set facts = '{"as_of": "Oct 27, 2026 (Scorecard Jun 2026; NCES 2024-25 costs; college Common Data Sets 2025-26)", "stats": {"undergrad_enrollment": 6684, "admit_rate": 0.84, "grad_rate_6yr": 0.53, "retention_rate": 0.77, "student_faculty_ratio": "18:1", "in_state_tuition_fees": 14277, "in_state_cost_of_attendance": 30449, "avg_net_price_all": 12759, "median_earnings_10yr": null, "drive_miles": 92, "drive_hours": 2}, "net_price_by_income": {"0-30000": 6162, "30001-48000": 4553, "48001-75000": 10154, "75001-110000": 14160, "110001-plus": 22333}, "business": {"school": "College of Business", "admission_model": "Admitted to NMU directly (2.25+ high school GPA); entry into the College of Business itself comes later — current GPA/credit thresholds weren’t confirmed online.", "class_size": "About 210 business degrees awarded in 2024-25", "academic_feel": "Small, hands-on and entrepreneurial; 19 programs including Ski Area Business Management and Risk Management & Insurance.", "recruiting_and_outcomes": "College cites a $48K average starting salary and 28% with internships (year not stated).", "signature_programs": ["Superior Fund student-managed investment fund", "The Big Pitch new-venture competition", "Internship and Executive Mentorship programs", "Ski Area Business Management"], "aacsb": true, "business_clubs": ["ENACTUS", "Beta Alpha Psi", "American Marketing Association", "Gamma Iota Sigma", "Society for Human Resource Management"], "how_it_fits_campus": "A small regional business college; students take NMU liberal studies alongside the business core."}, "sources": [{"label": "College Scorecard", "url": "https://collegescorecard.ed.gov/school/?171456-Northern-Michigan-University", "year": "2026 release"}, {"label": "NCES College Navigator", "url": "https://nces.ed.gov/collegenavigator/?id=171456", "year": "2024-25"}, {"label": "NMU College of Business", "url": "https://nmu.edu/business/academics", "year": "current"}, {"label": "NMU cost of attendance", "url": "https://nmu.edu/financialaid/attendance", "year": "2026-27"}, {"label": "NMU Common Data Set 2025-26", "url": "https://nmu.edu/institutionaleffectiveness/sites/institutionaleffectiveness/files/2026-01/Northern-Michigan-University-CDS-2025-2026.pdf", "year": "2025-26"}, {"label": "NMU housing requirement", "url": "https://nmu.edu/housing/housing-requirement-policy-update", "year": "Fall 2026"}, {"label": "NMU College of Business", "url": "https://nmu.edu/business/home", "year": "current"}, {"label": "NMU State of the College", "url": "https://nmu.edu/epc/sites/epc/files/2025-10/State-of-the-College-2025.pptx.pdf", "year": "2025"}], "housing": {"first_year_requirement": "Required: from Fall 2026 all single undergrads live in the halls (until four semesters, age 21, or other exemptions)", "room_and_board": "$13,680 ($7,150 housing + $6,530 food, 2026-27)", "residence_options": ["The Woods complex (suites by dining)", "The Quad (shared-bedroom suites)", "Spooner Hall apartments"], "business_living_community": null, "application_opens": "Fall 2027 not posted yet. Apply in MyNMU with a $50 fee and $200 advance payment; room selection in February.", "notes": "Halls are split into houses of 50–60. Add a $150/semester comprehensive fee."}, "campus": {"setting": "Marquette, a small city of about 20,000 on Lake Superior", "pct_in_state": "About 76% of undergrads", "student_orgs": "300+ organizations", "greek_life": "Small", "athletics": "NCAA Division II (GLIAC); men’s hockey Division I (CCHA)", "traditions": ["Superior Dome — one of the world’s largest wooden domes", "Outdoor recreation on Lake Superior", "Wildcats"], "climate_note": "Lake-effect snow; Marquette averages about 149 inches (NWS, via Spectrum News)."}}'::jsonb where id = '00000000-0000-4000-a000-000000000004';
select name, facts->'housing'->>'room_and_board' as rb, facts->'campus'->>'athletics' as ath from colleges where facts is not null order by priority;
